#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
decode_zcid_standalone.py

File độc lập để giải mã Zalo enc_ver=v2 bằng zcid + zcid_ext.
KHÔNG import utils/get_loginInfo.py.

Cài thư viện:
    pip install cryptography

Cách dùng nhanh:
    python decode_zcid_standalone.py --zcid "..." --zcid-ext "0f818e" --cipher-file data.txt --out decoded.json

Hoặc dán trực tiếp zcid/zcid_ext/cipher vào các biến CONFIG bên dưới rồi chạy:
    python decode_zcid_standalone.py
"""

from __future__ import annotations

import argparse
import base64
import hashlib
import json
import sys
from pathlib import Path
from typing import Any, Optional

from cryptography.hazmat.primitives import padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes


# ========================== CONFIG DÁN NHANH Ở ĐÂY ==========================

ZCID = """
99B33D1EF01B7AF40ECCACD4BAA19DCADB6987E5859398A2D11E5A2A8782D84E9C255E910C867ACA328CCB35EB8C2902E04C84A2770234F016C6BE83646A95D1B46A10E2309D697EA8BD3A5F57374977D701E3FBBB03C25A86D4D4FAAD826336
""".strip()

ZCID_EXT = "0f818e"

# Dán chuỗi params hoặc response.data vào đây nếu không muốn dùng --cipher-file.
# Lưu ý: phải giữ nguyên ký tự + / =, không được để + biến thành dấu cách.
CIPHER_B64 = """

""".strip()

# Tên file output mặc định.
DEFAULT_OUTPUT = "zcid_decoded.json"


# =============================== CORE DECRYPT ===============================

def _split_even_odd(text: str) -> tuple[list[str], list[str]]:
    """Tách chuỗi thành ký tự vị trí chẵn/lẻ theo logic Zalo Web."""
    return list(text[::2]), list(text[1::2])


def build_encrypt_key(zcid: str, zcid_ext: str) -> str:
    """
    Sinh encryptKey cho enc_ver=v2.

    Công thức đang dùng trong source gốc:
      md5_hex = MD5(zcid_ext).upper()
      encryptKey = md5_even[:8] + zcid_even[:12] + reversed(zcid_odd)[:12]

    Kết quả phải dài 32 ký tự để làm AES-256 key.
    """
    zcid = clean_text(zcid)
    zcid_ext = clean_text(zcid_ext)

    if not zcid:
        raise ValueError("zcid rỗng")
    if not zcid_ext:
        raise ValueError("zcid_ext rỗng")

    md5_hex = hashlib.md5(zcid_ext.encode("utf-8")).hexdigest().upper()
    md5_even, _ = _split_even_odd(md5_hex)
    zcid_even, zcid_odd = _split_even_odd(zcid)

    encrypt_key = (
        "".join(md5_even[:8])
        + "".join(zcid_even[:12])
        + "".join(list(reversed(zcid_odd))[:12])
    )

    if len(encrypt_key) != 32:
        raise ValueError(f"encryptKey không đủ 32 ký tự: len={len(encrypt_key)}")

    return encrypt_key


def decrypt_zalo_v2_cipher(zcid: str, zcid_ext: str, cipher_b64: str, show_key: bool = False) -> str:
    """
    Giải mã ciphertext Base64 của Zalo enc_ver=v2.

    Thuật toán:
      - AES-CBC
      - Key: build từ zcid + zcid_ext
      - IV: 16 byte zero
      - Padding: PKCS7
    """
    cipher_b64 = clean_base64(cipher_b64)
    if not cipher_b64:
        raise ValueError("cipher_b64 rỗng")

    encrypt_key = build_encrypt_key(zcid, zcid_ext)
    if show_key:
        print(f"encryptKey = {encrypt_key}")

    try:
        ciphertext = base64.b64decode(cipher_b64, validate=True)
    except Exception:
        # Một số dữ liệu copy từ URL/body có thể thiếu padding hoặc lẫn khoảng trắng.
        ciphertext = base64.b64decode(fix_base64_padding(cipher_b64), validate=False)

    key = encrypt_key.encode("utf-8")
    iv = bytes(16)

    cipher = Cipher(algorithms.AES(key), modes.CBC(iv))
    decryptor = cipher.decryptor()
    plaintext_padded = decryptor.update(ciphertext) + decryptor.finalize()

    unpadder = padding.PKCS7(128).unpadder()
    plaintext = unpadder.update(plaintext_padded) + unpadder.finalize()

    return plaintext.decode("utf-8")


# ================================ UTILITIES =================================

def clean_text(value: Optional[str]) -> str:
    if value is None:
        return ""
    return str(value).strip().strip('"').strip("'")


def clean_base64(value: Optional[str]) -> str:
    """
    Làm sạch Base64 an toàn.
    Không xóa dấu + / =.
    Chỉ bỏ xuống dòng, tab, khoảng trắng ngoài ý muốn.
    """
    if value is None:
        return ""
    text = str(value).strip().strip('"').strip("'")
    text = text.replace("\r", "").replace("\n", "").replace("\t", "")
    text = text.replace(" ", "")
    return text


def fix_base64_padding(value: str) -> str:
    value = clean_base64(value)
    missing = len(value) % 4
    if missing:
        value += "=" * (4 - missing)
    return value


def try_parse_json(text: str) -> Any:
    try:
        return json.loads(text)
    except Exception:
        return None


def save_output(plaintext: str, output_path: Path) -> None:
    output_path.parent.mkdir(parents=True, exist_ok=True)

    parsed = try_parse_json(plaintext)
    if parsed is not None:
        output_path.write_text(
            json.dumps(parsed, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    else:
        output_path.write_text(plaintext, encoding="utf-8")


def read_cipher_from_args(args: argparse.Namespace) -> str:
    if args.cipher_file:
        return Path(args.cipher_file).read_text(encoding="utf-8").strip()
    if args.cipher:
        return args.cipher.strip()
    return CIPHER_B64


# =================================== CLI =====================================

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Standalone decoder for Zalo enc_ver=v2 zcid/zcid_ext ciphertext.",
    )
    parser.add_argument("--zcid", default=ZCID, help="Giá trị zcid")
    parser.add_argument("--zcid-ext", default=ZCID_EXT, help="Giá trị zcid_ext")
    parser.add_argument("--cipher", default="", help="Chuỗi Base64 cần giải mã")
    parser.add_argument("--cipher-file", default="", help="File .txt chứa chuỗi Base64 cần giải mã")
    parser.add_argument("--out", default=DEFAULT_OUTPUT, help="File output .json/.txt")
    parser.add_argument("--show-key", action="store_true", help="In encryptKey ra console để debug")
    parser.add_argument("--print", action="store_true", help="In plaintext ra console")
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    zcid = clean_text(args.zcid)
    zcid_ext = clean_text(args.zcid_ext)
    cipher_b64 = read_cipher_from_args(args)

    if not cipher_b64 or cipher_b64 == "PASTE_CIPHER_BASE64_HERE":
        print("❌ Chưa có cipher để giải mã.")
        print("Cách 1: dán vào biến CIPHER_B64 trong file.")
        print("Cách 2: chạy: python decode_zcid_standalone.py --cipher-file data.txt --out decoded.json")
        return 1

    try:
        plaintext = decrypt_zalo_v2_cipher(
            zcid=zcid,
            zcid_ext=zcid_ext,
            cipher_b64=cipher_b64,
            show_key=bool(args.show_key),
        )

        out_path = Path(args.out)
        save_output(plaintext, out_path)

        print(f"✅ Giải mã thành công: {out_path.resolve()}")

        parsed = try_parse_json(plaintext)
        if parsed is not None:
            print("✅ Plaintext là JSON hợp lệ")
        else:
            print("ℹ️ Plaintext không phải JSON, đã lưu dạng text")

        if getattr(args, "print", False):
            print("\n========== PLAINTEXT ==========")
            print(plaintext)

        return 0

    except Exception as exc:
        print("❌ Giải mã thất bại")
        print(f"Lỗi: {exc}")
        print("\nGợi ý kiểm tra:")
        print("- zcid và zcid_ext có đúng cùng request/response không")
        print("- cipher có bị thiếu ký tự không")
        print("- dấu + trong Base64 có bị biến thành khoảng trắng không")
        print("- data có đúng enc_ver=v2 không")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
